                          <div className="bg-red-50 p-4 rounded-lg text-center">
                            <p className="text-2xl font-bold text-red-600">{stats.terminated}</p>
                            <p className="text-sm text-gray-600">已終止</p>
                          </div>
                        </>
                      );
                    })()
